edits.old:
GridView.builder(
      shrinkWrap: true,
      physics: const NeverScrollableScrollPhysics(),
      gridDelegate: const SliverGridDelegateWithMaxCrossAxisExtent(
        maxCrossAxisExtent: 400,
        mainAxisSpacing: 24,
        crossAxisSpacing: 24,
        childAspectRatio: 1.35,
      ),
      itemCount: portalApps.length,
      itemBuilder: (context, index) {
        final app = portalApps[index];
        final name = app['name'] as String;
        final url = app['url'] as String;
        final icon = app['icon'] as IconData;
        final description = app['description'] as String;
        final accentColor = app['color'] as Color;

        final isAuthorized = _hasAccessToPortal(authState.role ?? 'Guest', url);

        return AnimatedOpacity(
          duration: const Duration(milliseconds: 300),
          opacity: isAuthorized ? 1.0 : 0.45,
          child: Container(
            decoration: BoxDecoration(
              color: isAuthorized 
                  ? PrimeActionPalette.of(context, PrimeActionTone.primary).accent
                  : PrimeActionPalette.of(context, PrimeActionTone.primary).accent,
              borderRadius: BorderRadius.circular(16),
              border: Border.all(
                color: isAuthorized 
                    ? accentColor.withValues(alpha: 0.25)
                    : PrimeActionPalette.of(context, PrimeActionTone.primary).accent,
                width: 1.5,
              ),
              boxShadow: isAuthorized ? [
                BoxShadow(
                  color: accentColor.withValues(alpha: 0.05),
                  blurRadius: 16,
                  offset: const Offset(0, 8),
                )
              ] : null,
            ),
            child: Material(
              color: PrimeActionPalette.of(context, PrimeActionTone.primary).accent,
              child: InkWell(
                borderRadius: BorderRadius.circular(16),
                onTap: isAuthorized ? () {
                  launchUrl(Uri.parse(url), mode: LaunchMode.externalApplication);
                } : null,
                child: Padding(
                  padding: const EdgeInsets.all(24),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(
                        mainAxisAlignment: MainAxisAlignment.spaceBetween,
                        children: [
                          Container(
                            padding: const EdgeInsets.all(12),
                            decoration: BoxDecoration(
                              color: PrimeActionPalette.tintSurface(context, accentColor),
                              shape: BoxShape.circle,
                              border: Border.all(
                                color: accentColor.withValues(alpha: 0.2),
                              ),
                            ),
                            child: Icon(
                              icon,
                              color: PrimeActionPalette.onTint(context, accentColor),
                              size: 24,
                            ),
                          ),
                          if (!isAuthorized)
                            Container(
                              padding: const EdgeInsets.all(6),
                              decoration: BoxDecoration(
                                color: PrimeActionPalette.of(context, PrimeActionTone.primary).accent,
                                shape: BoxShape.circle,
                              ),
                              child: Icon(
                                LucideIcons.lock,
                                color: PrimeActionPalette.of(context, PrimeActionTone.primary).accent,
                                size: 14,
                              ),
                            )
                          else
                            Icon(
                              LucideIcons.arrowRight,
                              color: PrimeActionPalette.of(context, PrimeActionTone.primary).accent,
                              size: 18,
                            ),
                        ],
                      ),
                      const SizedBox(height: 16),
                      Text(
                        name,
                        style: theme.typography.h3.copyWith(
                          fontWeight: FontWeight.bold,
                          color: PrimeActionPalette.of(context, PrimeActionTone.primary).accent,
                        ),
                      ),
                      const SizedBox(height: 8),
                      Expanded(
                        child: Text(
                          description,
                          style: theme.typography.bodyMedium.copyWith(
                            color: PrimeActionPalette.of(context, PrimeActionTone.primary).accent,
                            fontSize: 12,
                            height: 1.4,
                          ),
                          maxLines: 3,
                          overflow: TextOverflow.ellipsis,
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            ),
          ),
        );
      }

